import type { RoomType } from "./types";

export interface SampleImage {
  url: string;
  roomType: RoomType;
  label: string;
}

// Original illustrations generated by client/scripts/generate-samples.mjs.
export const SAMPLE_IMAGES: SampleImage[] = [
  { url: "/samples/bathroom-wet-floor.jpg", roomType: "bathroom", label: "Baño con piso mojado" },
  { url: "/samples/stairs-no-handrail.jpg", roomType: "stairs", label: "Escalera sin barandal" },
];

export async function fetchSample(sample: SampleImage): Promise<Blob> {
  const res = await fetch(sample.url);
  if (!res.ok) throw new Error("No se pudo cargar la imagen de prueba.");
  return res.blob();
}
